// An image layer. model maps image to ground; it is null for images with no geolocation (a plain PNG or JPEG).
export function imageLayer(source, model = null) {
  return { kind: 'image', source, model };
}

base.src/geo.js:
// The corners of a square of side sizeMetres around a (lon, lat) centre.
export function squareAround([lon, lat], sizeMetres) {
  const half = sizeMetres / 2;
  const dLat = half / 111320;
  const dLon = half / (111320 * Math.cos((lat * Math.PI) / 180));
  return [[lon - dLon, lat + dLat], [lon + dLon, lat + dLat], [lon + dLon, lat - dLat], [lon - dLon, lat - dLat]];
}

head.src/commands/chip.js:
import { squareAround } from '../geo.js';

export const chipByArea = {
  id: 'chip.area',
  label: 'Chip by Preset Area',
  enabled: (layer) => layer?.kind === 'image',
  run(layer, centre, sizeMetres) {
    const corners = squareAround(centre, sizeMetres).map(([lon, lat]) => layer.model.groundToImage(lon, lat));
    return layer.source.window(corners);
  },
};
